    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Articles were included if they were peer-reviewed articles published in English or Spanish (the languages of the authors) that reported mental health outcomes in clinical staff managing high-risk infectious disease outbreaks. We considered studies on all healthcare staff in all settings as relevant. Studies of methodologies including quantitative studies, qualitative studies, and anecdotal accounts, reporting original results were included.",
      "reason": "The manuscript specifies the inclusion criteria regarding the population (clinical staff managing high-risk infectious disease outbreaks), outcomes (mental health outcomes), and study designs (quantitative, qualitative, and anecdotal accounts reporting original results)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Articles were included if they were peer-reviewed articles published in English or Spanish (the languages of the authors) that reported mental health outcomes in clinical staff managing high-risk infectious disease outbreaks.",
      "reason": "The manuscript specifies language restrictions (English or Spanish) and publication status (peer-reviewed articles)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We defined high and low exposures as direct contact with infected patients, or work in wards where direct contact was considered highly likely (e.g. critical care, designated treatment wards, emergency departments) compared to clinicians working without direct contact or work in hospital areas where direct contact was unlikely. A narrative synthesis of risk factors was conducted across all studies regardless of methodology.",
      "reason": "The manuscript defines the groups used for synthesis (high vs. low exposure) and mentions the narrative synthesis approach."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review inclusion criteria."
    }
  ],
  "confidence": 95
}

